#!/usr/bin/env python3
"""Regenerate Bolt's locale-independent, per-scalar Unicode case table.

The checked-in table pins the generating Python Unicode database version. This
maintenance script is NOT invoked by normal builds or by the installer.
"""
from pathlib import Path
import unicodedata

out=Path(__file__).resolve().parents[1]/'include/bolt/library/detail/UnicodeCase.hpp'
lines=['#pragma once','#include <algorithm>','#include <array>','#include <cstdint>',
       '// Generated by tools/generate-unicode-case.py; Unicode '+unicodedata.unidata_version+'.',
       '// Per-scalar default mapping; no locale or context-dependent rules.',
       'namespace bolt::library::unicode_case {',
       'inline constexpr const char* Version="'+unicodedata.unidata_version+'";',
       'struct Mapping {char32_t from; std::array<char32_t,3> to; std::uint8_t count;};']
for method,name in [('upper','Upper'),('lower','Lower')]:
    entries=[]
    for value in range(0x110000):
        if 0xD800<=value<=0xDFFF: continue
        source=chr(value); mapped=getattr(source,method)()
        if source!=mapped:
            assert len(mapped)<=3
            target=', '.join(hex(ord(c)) for c in mapped)
            entries.append('    {'+hex(value)+', {'+target+'}, '+str(len(mapped))+'},')
    lines+=['inline constexpr std::array<Mapping,'+str(len(entries))+'> '+name+'{{']+entries+['}};']
lines+=['template<std::size_t N> inline const Mapping* find(const std::array<Mapping,N>& map,char32_t value) {',
        '    auto it=std::lower_bound(map.begin(),map.end(),value,[](const Mapping& m,char32_t c){return m.from<c;});',
        '    return it!=map.end()&&it->from==value?&*it:nullptr;', '}', '}']
out.write_text('\n'.join(lines)+'\n',encoding='utf-8')
print(f'{out.name}: Unicode {unicodedata.unidata_version}')
